window.COBIT_CONTROLS = window.COBIT_CONTROLS || [];
window.COBIT_CONTROLS.push(...
[
{"objective":"DSS01","purpose":"BT operasyonlarının (iş zamanlama, altyapı izleme, dış kaynaklı hizmetler, ortam ve tesisler) öngörülebilir ve tekrarlanabilir biçimde yürütülmesi, iş süreçlerini destekleyen sistemlerin zamanında ve doğru çalışmasını sağlar. Operasyonel disiplin zayıf olduğunda tamamlanmayan toplu işler, fark edilmeyen kapasite sorunları veya çevresel arızalar doğrudan iş kesintisine ve veri bütünlüğü sorunlarına dönüşür.","auditFocus":"Kıdemli denetçi, finansal ve kritik iş verisini işleyen zamanlanmış işlerin yetkili şekilde tanımlanıp değiştirildiğini, hata ve sapmaların izlenip çözüldüğünü kanıtlarla doğrular. Ayrıca dış kaynak sağlayıcıların ve veri merkezi kontrollerinin kurumun güvence beklentisini karşılayıp karşılamadığını, bağımsız güvence raporları ve tamamlayıcı kullanıcı kontrolleri üzerinden değerlendirir.","keyRisks":["Başarısız veya atlanan zamanlanmış işlerin fark edilmemesi nedeniyle eksik ya da hatalı veri işlenmesi","Dış kaynaklı hizmetlerde güvence boşluğu ve tamamlayıcı kullanıcı kontrollerinin uygulanmaması","Elektrik, soğutma veya yangın gibi çevresel tehditlerin kritik altyapıda uzun süreli kesintiye yol açması"],"practices":[
{"code":"DSS01.01","name":"Perform operational procedures.","title":"Operasyon prosedürleri ve iş zamanlama yönetimi","expectation":"Rutin operasyon faaliyetleri (zamanlanmış işler, toplu iş zincirleri, gün sonu işlemleri, vardiya devir teslimi) belgelenmiş prosedürlere dayanır ve iş zamanlama aracındaki tanımlar yalnızca yetkili kişilerce, değişiklik süreci üzerinden güncellenir. Başarısız veya geciken işler kuruma göre belirlenmiş eşikler ve sorumluluk matrisine göre izlenir; yeniden çalıştırmalar kayıt altına alınır ve gerekçelendirilir. Geliştirme ekiplerinin üretim iş tanımlarına müdahale yetkisi operasyon ekibinden ayrıştırılmıştır.","design":"İş zamanlama aracında oluşturma ve değiştirme yetkisinin kısıtlı olup olmadığı, hata uyarılarının tanımlı alıcılara yönlendirilip yönlendirilmediği ve yeniden çalıştırma için onay kuralı tasarlanıp tasarlanmadığı incelenir.","operating":"Denetim dönemine ait tam iş çalıştırma geçmişi zamanlayıcıdan alınıp tamlığı doğrulanır; başarısız işler ve manuel müdahaleler arasından risk bazlı seçilen örneklerde olay kaydı, çözüm ve onay izi incelenir. İş tanımlarındaki değişiklikler değişiklik kayıtlarıyla eşleştirilir.","evidence":["İş zamanlama aracından denetim dönemine ait çalıştırma geçmişi ve hata listesi","Zamanlayıcıda iş tanımlama ve değiştirme yetkisine sahip kullanıcı listesi","Operasyon el kitabı ve vardiya devir teslim kayıtları","Başarısız işler için açılmış olay kayıtları ve yeniden çalıştırma onayları"],"findings":["Başarısız gece işlerinin bir kısmı için olay kaydı açılmadığı ve yeniden çalıştırmaların gerekçesinin belgelenmediği görülmüştür.","İş zamanlama aracında geliştirici hesaplarının üretim iş tanımlarını değiştirme yetkisine sahip olduğu tespit edilmiştir."],"iso":["5.37","8.32"],"clauses":["8.1"],"itgc":"operations"},
{"code":"DSS01.02","name":"Manage outsourced I&T services.","title":"Dış kaynaklı BT hizmetlerinin operasyonel güvencesi","expectation":"Barındırma, bulut ve yönetilen hizmet gibi dış kaynaklı operasyonlar için sözleşmelerde güvenlik, hizmet düzeyi, denetim hakkı ve olay bildirimi gereksinimleri tanımlıdır. Kurum, sağlayıcıdan kuruma göre belirlenmiş periyotta bağımsız güvence raporu veya eşdeğer kanıt alır, raporun kapsamını ve istisnalarını değerlendirir ve rapordaki tamamlayıcı kullanıcı kontrollerini kendi tarafında uygular. Hizmet performansı, sorumlusu belli bir hizmet sahibi tarafından düzenli olarak gözden geçirilir.","design":"Tedarikçi yönetim prosedürünün güvence alma, rapor değerlendirmesi ve tamamlayıcı kullanıcı kontrollerinin sahiplendirilmesi adımlarını içerip içermediği değerlendirilir.","operating":"Kritik dış kaynaklı hizmetlerin listesi sözleşme envanteriyle mutabakatlanır; risk bazlı seçilen sağlayıcılar için güvence raporunun dönemi kapsadığı, istisnaların değerlendirildiği ve tamamlayıcı kontrollerin uygulandığı kanıtlarla doğrulanır.","evidence":["Dış kaynaklı hizmetler envanteri ve sözleşmelerin güvenlik, SLA ve denetim hakkı maddeleri","Sağlayıcı bağımsız güvence raporları ve kurumun rapor değerlendirme notları","Tamamlayıcı kullanıcı kontrolleri eşleştirme tablosu ve uygulama kanıtları","Hizmet düzeyi gözden geçirme toplantı tutanakları"],"findings":["Barındırma sağlayıcısının güvence raporunun denetim döneminin yalnızca bir bölümünü kapsadığı ve aradaki boşluk için ek güvence alınmadığı görülmüştür.","Güvence raporunda belirtilen tamamlayıcı kullanıcı kontrollerinin kurum içinde sahiplendirilmediği tespit edilmiştir."],"iso":["5.19","5.20","5.22","5.23"],"clauses":["8.1"],"itgc":"operations"},
{"code":"DSS01.03","name":"Monitor I&T infrastructure.","title":"Altyapı izleme ve kapasite takibi","expectation":"Kritik sunucu, veri tabanı, ağ ve bulut bileşenleri merkezi bir izleme aracıyla sürekli izlenir; kullanılabilirlik, performans ve kapasite eşikleri hizmetin önemine göre kuruma göre belirlenmiş değerlerle tanımlanır. Eşik aşımları otomatik uyarı üretir ve uyarılar olay yönetimine bağlanır; izleme dışında bırakılan varlıklar gerekçelendirilir. Kapasite eğilimleri dönemsel olarak raporlanır ve planlamaya girdi sağlar.","design":"İzleme kapsamının varlık envanterindeki kritik bileşenlerin tümünü içerip içermediği ve uyarıların sahipli bir çözüm akışına bağlanıp bağlanmadığı incelenir.","operating":"Varlık envanteri ile izleme aracındaki varlık listesi karşılaştırılarak kapsam boşlukları belirlenir; dönem içinden seçilen kritik uyarıların olay kaydına dönüştüğü ve zamanında ele alındığı izlenir.","evidence":["İzleme aracındaki izlenen varlık listesi ile varlık envanteri karşılaştırması","Eşik tanımları ve uyarı yönlendirme kuralları","Dönem içi kritik uyarılar ve ilişkili olay kayıtları","Kapasite eğilim raporları"],"findings":["Yeni devreye alınan bazı üretim sunucularının izleme aracına eklenmediği görülmüştür.","Disk doluluk uyarılarının sahipsiz bir ortak e-posta kutusuna gittiği ve takip edilmediği tespit edilmiştir."],"iso":["8.6","8.16"],"clauses":["9.1"],"itgc":"operations"},
{"code":"DSS01.04","name":"Manage the environment.","title":"Veri merkezi çevresel koruma önlemleri","expectation":"Veri merkezi ve sistem odalarında elektrik sürekliliği (UPS, jeneratör), soğutma, nem, yangın algılama ve söndürme ile su baskını algılama önlemleri risk değerlendirmesine dayalı olarak kurulmuştur. Ekipmanlar üretici önerileri ve kuruma göre belirlenmiş bakım planı çerçevesinde bakımdan geçirilir, alarmlar sürekli izlenen bir noktaya iletilir. Jeneratör ve UPS gibi bileşenler yük altında periyodik olarak test edilir.","design":"Çevresel tehditlerin risk değerlendirmesinde ele alınıp alınmadığı ve her tehdit için algılama, alarm ve müdahale önleminin tanımlanıp tanımlanmadığı değerlendirilir.","operating":"Dönem içi bakım ve test kayıtları bakım planıyla karşılaştırılır; izinli yerinde gözlemle alarm panelleri, sensörler ve söndürme sisteminin durumu incelenir, alarm kayıtlarından seçilen olayların takibi doğrulanır.","evidence":["UPS, jeneratör, klima ve yangın söndürme sistemlerine ait bakım sözleşmeleri ve servis raporları","Jeneratör ve UPS yük testi kayıtları","Çevresel izleme sistemi alarm kayıtları","Veri merkezi yerinde gözlem notları"],"findings":["Jeneratör yük testinin planlanan dönemde yapılmadığı ve ilgili bakım raporunun bulunmadığı görülmüştür.","Sistem odasındaki sıcaklık alarmlarının mesai dışında hiçbir sorumluya iletilmediği tespit edilmiştir."],"iso":["7.5","7.11","7.13"],"clauses":["6.1"],"itgc":"operations"},
{"code":"DSS01.05","name":"Manage facilities.","title":"BT tesislerinin yönetimi ve fiziksel altyapı düzeni","expectation":"Veri merkezi, kabinler ve kablolama için yerleşim, kablolama standardı, iş sağlığı ve güvenliği gereksinimleri ile tesis bakımı planlanmış ve sorumluları belirlenmiştir. Kablolar korunur ve etiketlenir, tesis değişiklikleri onaylı yapılır ve tesis sorunları kayıt altına alınır. Ortak kullanımlı (colocation) tesislerde sağlayıcı ile sorumluluk paylaşımı yazılıdır.","design":"Tesis yönetimi prosedürünün bakım planını, kablolama standardını, tesis değişikliği onayını ve sağlayıcı sorumluluklarını kapsayıp kapsamadığı incelenir.","operating":"Tesis bakım ve değişiklik kayıtlarından risk bazlı örnekler seçilerek onay ve tamamlanma izi doğrulanır; yerinde gözlemle kablolama düzeni, etiketleme ve ekipman yerleşimi incelenir.","evidence":["Tesis bakım planı ve tamamlanmış iş emirleri","Kablolama şemaları ve etiketleme standardı","Colocation sözleşmesi ve sorumluluk matrisi","Yerinde gözlem kontrol listesi"],"findings":["Kabinlerde etiketsiz ve belgelenmemiş kablo bağlantıları bulunduğu gözlemlenmiştir.","Tesis bakım iş emirlerinin bir kısmının tamamlanma kanıtı olmadan açık kaldığı tespit edilmiştir."],"iso":["7.8","7.12","7.13"],"clauses":[],"itgc":"operations"}
]},
{"objective":"DSS02","purpose":"Kullanıcı taleplerinin ve olayların tutarlı biçimde kaydedilip önceliklendirilmesi, kesintilerin iş üzerindeki etkisini sınırlar ve normal hizmetin hızla geri gelmesini sağlar. Bu süreç aynı zamanda erişim ve yazılım kurulumu gibi kontrol açısından önemli taleplerin onaylı ve izlenebilir şekilde yerine getirilmesinin temelidir.","auditFocus":"Denetçi, olayların tam ve doğru kaydedildiğini, önceliklendirmenin iş etkisine dayandığını ve kritik olayların tanımlı eskalasyonla zamanında çözüldüğünü kanıtlarla doğrular. Güvenlik olaylarının ayrı müdahale sürecine aktarılması ve hizmet taleplerinin onay alınmadan karşılanmaması özellikle incelenir.","keyRisks":["Olayların kaydedilmemesi veya yanlış önceliklendirilmesi nedeniyle kritik kesintilerin geç fark edilmesi","Onaysız hizmet taleplerinin (erişim, yazılım kurulumu gibi) yerine getirilmesi","Güvenlik ihlallerinin sıradan arıza gibi ele alınması ve delillerin kaybolması"],"practices":[
{"code":"DSS02.01","name":"Define classification schemes for incidents and service requests.","title":"Olay ve talep sınıflandırma ile öncelik şeması","expectation":"Olay ve hizmet talepleri için kategori, etki ve aciliyet kriterleri, öncelik matrisi ve her öncelik için hedef müdahale ve çözüm süreleri kuruma göre belirlenmiştir ve hizmet düzeyi anlaşmalarıyla uyumludur. Güvenlik olayı, büyük olay ve problem kavramları birbirinden açıkça ayrılmış, eskalasyon kuralları belgelenmiştir.","design":"Şemanın iş etkisini esas alıp almadığı, güvenlik olaylarını ayırt edecek kriter içerip içermediği ve SLA hedefleriyle tutarlı olup olmadığı değerlendirilir.","operating":"Hizmet masası aracındaki kategori ve öncelik yapılandırması onaylı şemayla karşılaştırılır; seçilen kayıtlarda önceliğin şemaya uygun atanıp atanmadığı yeniden uygulama ile kontrol edilir.","evidence":["Onaylı olay ve talep sınıflandırma ile öncelik matrisi","Hizmet masası aracı yapılandırma ekran görüntüleri","Hizmet düzeyi anlaşmaları","Büyük olay ve güvenlik olayı tanım dokümanı"],"findings":["Araçta tanımlı öncelik matrisinin onaylı prosedürdeki matristen farklı olduğu görülmüştür.","Güvenlik olaylarını ayırt edecek bir kategori veya kriter tanımlanmadığı tespit edilmiştir."],"iso":["5.24","5.25"],"clauses":["7.5"],"itgc":"operations"},
{"code":"DSS02.02","name":"Record, classify and prioritize requests and incidents.","title":"Taleplerin ve olayların kaydı, sınıflandırılması ve önceliklendirilmesi","expectation":"Telefon, e-posta, portal veya izleme uyarısı gibi hangi kanaldan gelirse gelsin tüm olay ve talepler tek bir araçta kayıt altına alınır, şemaya göre sınıflandırılır ve öncelik atanır. Kayıtlar tarih-saat, etkilenen hizmet, bildiren kullanıcı ve atanan grup bilgilerini içerir; sonradan yapılan öncelik değişiklikleri gerekçeli ve izlenebilirdir.","design":"Tüm giriş kanallarının kayıt aracına bağlanıp bağlanmadığı ve zorunlu alanların araç tarafından zorlanıp zorlanmadığı incelenir.","operating":"Dönemin tüm kayıt dökümü alınarak zorunlu alanların doluluğu veri analiziyle değerlendirilir; izleme uyarılarından seçilen örneklerin kayda dönüştüğü izlenir ve öncelik değişiklikleri gerekçe açısından incelenir.","evidence":["Dönem içi olay ve talep kayıt dökümü","İzleme uyarılarından kayda dönüşüm eşleştirmesi","Öncelik değişikliği denetim izi","Kayıt prosedürü"],"findings":["Telefonla bildirilen bazı olayların kayda alınmadan çözüldüğü görülmüştür.","Kayıtların bir kısmında etkilenen hizmet alanının boş bırakıldığı tespit edilmiştir."],"iso":["5.25","6.8"],"clauses":[],"itgc":"operations"},
{"code":"DSS02.03","name":"Verify, approve and fulfill service requests.","title":"Hizmet taleplerinin doğrulanması, onaylanması ve karşılanması","expectation":"Erişim, donanım ve yazılım kurulumu gibi standart talep türlerinin her biri için yetkili onaycılar ve ön tanımlı karşılama adımları belirlenmiştir. Talep sahibinin kimliği ve talebin uygunluğu doğrulanmadan ve gerekli onay alınmadan talep yerine getirilmez; değişiklik niteliğindeki talepler değişiklik yönetimine yönlendirilir.","design":"Talep kataloğundaki her tür için onay akışının araçta zorunlu kılınıp kılınmadığı ve talep sahibinin kendi talebini onaylayamayacağı şekilde tasarlanıp tasarlanmadığı değerlendirilir.","operating":"Dönem içinde karşılanan taleplerden, özellikle erişim ve yazılım kurulumu türlerinde risk bazlı örnekler seçilir; onayın karşılamadan önce ve yetkili kişi tarafından verildiği zaman damgalarıyla doğrulanır.","evidence":["Hizmet talep kataloğu ve onay matrisi","Karşılanmış taleplerin onay ve tamamlanma zaman damgaları","İş akışı yapılandırması","Onaycı yetki listesi"],"findings":["Bazı yazılım kurulum taleplerinin onay tarihinden önce karşılandığı görülmüştür.","Talep sahibinin aynı zamanda onaycı olabildiği iş akışları bulunduğu tespit edilmiştir."],"iso":["5.18"],"clauses":[],"itgc":"operations"},
{"code":"DSS02.04","name":"Investigate, diagnose and allocate incidents.","title":"Olayların incelenmesi, teşhisi ve doğru gruba atanması","expectation":"Olaylar bilinen hata kayıtları ve bilgi bankası kullanılarak ilk seviyede teşhis edilir; çözülemeyenler tanımlı eskalasyon kurallarına göre uzman gruplara veya tedarikçilere atanır. Güvenlik olayı şüphesi taşıyan kayıtlar güvenlik ekibine aktarılır ve delil bütünlüğü korunur; tüm atama ve devirler kayıt üzerinde izlenebilir.","design":"Eskalasyon ve atama kurallarının, güvenlik şüphesinde devir adımının ve bilinen hata kaynaklarının sürece entegre edilip edilmediği incelenir.","operating":"Yüksek öncelikli olaylardan seçilen örneklerde atama zamanları, eskalasyonun kurala uygunluğu ve güvenlik içerikli olayların güvenlik ekibine zamanında aktarıldığı kayıt geçmişinden doğrulanır.","evidence":["Eskalasyon prosedürü ve atama kuralları","Seçilen olayların atama ve eskalasyon geçmişi","Güvenlik ekibine devredilen olay listesi","Bilgi bankası ve bilinen hata kayıtları"],"findings":["Kimlik avı şüphesi içeren bazı kayıtların güvenlik ekibine aktarılmadan hizmet masasında kapatıldığı görülmüştür.","Yüksek öncelikli olayların eskalasyonunun tanımlı süre aşıldıktan sonra yapıldığı tespit edilmiştir."],"iso":["5.25","5.26","5.28"],"clauses":[],"itgc":"operations"},
{"code":"DSS02.05","name":"Resolve and recover from incidents.","title":"Olayların çözülmesi ve hizmetin geri kazanılması","expectation":"Olay çözümleri belgelenir ve üretim ortamına dokunan düzeltmeler değişiklik yönetimi üzerinden yapılır; acil müdahaleler sonradan yetkili kişilerce onaylanır. Hizmetin geri geldiği kullanıcı teyidi veya izleme verisiyle doğrulanır, büyük olaylarda koordinasyon ve iletişim tanımlı bir rol tarafından yürütülür ve veri bütünlüğü etkisi ayrıca değerlendirilir.","design":"Çözüm adımlarının kaydedilmesi, acil değişikliklerin geriye dönük onayı ve büyük olay koordinasyon rolünün tasarlanıp tasarlanmadığı değerlendirilir.","operating":"Büyük olaylardan ve üretime müdahale içeren olaylardan seçilen örneklerde çözüm adımları, ilişkili acil değişiklik kayıtları ve hizmetin geri geldiğine ilişkin doğrulama incelenir.","evidence":["Büyük olay raporları ve iletişim kayıtları","Olaya bağlı acil değişiklik kayıtları ve sonradan alınan onaylar","Çözüm notları ve geri dönüş doğrulama kanıtı","Büyük olay yönetimi prosedürü"],"findings":["Olay çözümü sırasında üretimde yapılan yapılandırma değişikliklerinin değişiklik kaydına bağlanmadığı görülmüştür.","Bazı büyük olaylarda veri bütünlüğü etkisinin değerlendirilmediği tespit edilmiştir."],"iso":["5.26","8.32"],"clauses":[],"itgc":"operations"},
{"code":"DSS02.06","name":"Close service requests and incidents.","title":"Taleplerin ve olayların kapatılması","expectation":"Kayıtlar yalnızca çözüm doğrulandıktan sonra, kullanıcı teyidiyle veya kuruma göre belirlenmiş otomatik kapanış kuralı çerçevesinde kapatılır. Kapanışta çözüm kodu ve neden kategorisi girilir; tekrarlayan olaylar problem yönetimine aktarılmak üzere işaretlenir.","design":"Kapanış kriterlerinin ve çözüm kodu gibi zorunlu alanların araçta zorlanıp zorlanmadığı incelenir.","operating":"Kapatılmış kayıtlardan seçilen örneklerde çözüm doğrulaması ve kapanış kodu incelenir; dönem verisi üzerinden yeniden açılan kayıtlar ve aynı sorunla tekrarlayan kayıt kümeleri analiz edilir.","evidence":["Kapanış prosedürü ve otomatik kapanış kuralı","Kapatılmış kayıt örnekleri ve kullanıcı teyitleri","Yeniden açılan kayıt raporu","Kapanış kodu dağılım analizi"],"findings":["Kayıtların bir kısmının çözüm notu girilmeden kapatıldığı görülmüştür.","Aynı sorun için tekrar tekrar açılan kayıtların problem yönetimine aktarılmadığı tespit edilmiştir."],"iso":["5.27"],"clauses":[],"itgc":"operations"},
{"code":"DSS02.07","name":"Track status and produce reports.","title":"Durum takibi ve olay/talep performans raporlaması","expectation":"Açık kayıtların yaşlanması, SLA uyumu, eğilimler ve tekrarlayan olaylar düzenli raporlanır ve hizmet sahipleri ile yönetim tarafından gözden geçirilir. Rapor verilerinin kaynak araçla tutarlılığı sağlanır ve SLA ihlalleri için belirlenen aksiyonlar kapanışa kadar takip edilir.","design":"Rapor setinin karar vericilere ulaşıp ulaşmadığı ve SLA ihlalleri için takip mekanizması içerip içermediği değerlendirilir.","operating":"Seçilen dönemlere ait raporlar kaynak araç verisinden yeniden hesaplanarak doğrulanır; gözden geçirme toplantı tutanaklarında aksiyonların takibi incelenir.","evidence":["Dönemsel olay ve talep performans raporları","Kaynak araçtan alınan ham veri","Hizmet gözden geçirme toplantı tutanakları","SLA ihlali aksiyon listesi"],"findings":["Raporlanan SLA uyum oranının ham veriden yeniden hesaplanan değerle tutarsız olduğu görülmüştür.","Uzun süredir açık kayıtların raporlarda izlenmediği tespit edilmiştir."],"iso":[],"clauses":["9.1"],"itgc":""}
]},
{"objective":"DSS03","purpose":"Problem yönetimi, tekrarlayan olayların kök nedenlerini bularak kalıcı çözüm üretir ve hizmet kesintilerinin sıklığını ve maliyetini azaltır. Olaylara yalnızca geçici çözümle yanıt veren bir kurum aynı aksaklıkları tekrar tekrar yaşar ve kaynaklarını verimsiz kullanır.","auditFocus":"Denetçi, olay verisinden problem kayıtlarının sistematik biçimde türetildiğini, kök neden analizlerinin gerçekten yapıldığını ve kalıcı çözümlerin değişiklik yönetimi üzerinden uygulandığını inceler. Bilinen hataların hizmet masasıyla paylaşılması ve kapatılan problemlerin ilgili olayları gerçekten azaltıp azaltmadığı da değerlendirilir.","keyRisks":["Tekrarlayan olayların kök nedeninin bulunmaması nedeniyle süregelen kesintiler","Kalıcı çözümlerin değişiklik yönetimi dışında uygulanması","Bilinen hata ve geçici çözümlerin paylaşılmaması nedeniyle uzayan çözüm süreleri"],"practices":[
{"code":"DSS03.01","name":"Identify and classify problems.","title":"Problemlerin belirlenmesi ve sınıflandırılması","expectation":"Problem kayıtları tekrarlayan olaylar, büyük olaylar, tedarikçi bildirimleri ve eğilim analizleri gibi tanımlı tetikleyicilerle açılır, etki ve aciliyete göre önceliklendirilir ve ilgili olay kayıtlarıyla ilişkilendirilir. Her problem için bir sahip atanır.","design":"Problem açma tetikleyicilerinin, örneğin her büyük olay sonrası zorunlu problem kaydı gibi kuralların tanımlanıp tanımlanmadığı değerlendirilir.","operating":"Dönemdeki büyük olaylar ve tekrarlayan olay kümeleri veri analiziyle belirlenerek bunlar için problem kaydı açılıp açılmadığı karşılaştırılır.","evidence":["Problem yönetimi prosedürü ve tetikleyici tanımları","Problem kayıt listesi ve ilişkili olaylar","Büyük olay listesi","Olay eğilim analizi"],"findings":["Dönem içindeki büyük olayların bir kısmı için problem kaydı açılmadığı görülmüştür.","Problem kayıtlarının ilgili olay kayıtlarıyla ilişkilendirilmediği tespit edilmiştir."],"iso":["5.27"],"clauses":["10.2"],"itgc":"operations"},
{"code":"DSS03.02","name":"Investigate and diagnose problems.","title":"Kök neden analizi ve teşhis","expectation":"Problemler zaman çizelgesi, beş neden veya balık kılçığı gibi yapılandırılmış bir kök neden analizi yöntemiyle, ilgili teknik uzmanlar ve gerektiğinde tedarikçilerle birlikte incelenir. Analiz sonuçları, sürece katkıda bulunan kontrol zayıflıkları dahil olmak üzere problem kaydında belgelenir.","design":"Kök neden analizi için yöntem, sorumlu ve belgeleme şablonunun tanımlı olup olmadığı incelenir.","operating":"Seçilen problem kayıtlarında analizin gerçekten yapılıp belgelendiği, sonuçların kanıta dayandığı ve belirtiyi tekrar etmekle yetinmediği incelenir.","evidence":["Kök neden analizi şablonu ve tamamlanmış raporlar","Problem kayıtlarındaki analiz notları","Tedarikçi teknik analiz raporları","Analiz toplantı kayıtları"],"findings":["Kök neden alanına yalnızca belirtinin yeniden yazıldığı problem kayıtları bulunduğu görülmüştür.","Bazı problemlerin hiçbir analiz yapılmadan uzun süre açık bekletildiği tespit edilmiştir."],"iso":["5.27"],"clauses":["10.2"],"itgc":"operations"},
{"code":"DSS03.03","name":"Raise known errors.","title":"Bilinen hataların kaydı ve geçici çözümlerin paylaşılması","expectation":"Kök nedeni belirlenmiş ancak kalıcı çözümü henüz uygulanmamış problemler bilinen hata olarak kaydedilir ve geçici çözümler hizmet masasının erişebildiği bilgi bankasında yayımlanır. Bilinen hata kayıtları kalıcı çözümün durumuna göre güncel tutulur.","design":"Bilinen hata kayıtlarının hizmet masası aracıyla entegre olup olmadığı ve güncelleme sorumluluğunun tanımlanıp tanımlanmadığı incelenir.","operating":"Seçilen bilinen hata kayıtlarının bilgi bankasında yayımlandığı ve ilgili olaylarda kullanıldığı, kalıcı çözümü uygulanmış olanların kapatıldığı doğrulanır.","evidence":["Bilinen hata kayıtları dökümü","Bilgi bankası makaleleri","Bilinen hatalara bağlanmış olay kayıtları","Güncelleme sorumluluk tanımı"],"findings":["Geçici çözümlerin yalnızca uzman ekipte bilindiği ve bilgi bankasında yer almadığı görülmüştür.","Kalıcı çözümü uygulanmış hataların bilinen hata listesinde açık kaldığı tespit edilmiştir."],"iso":["5.27"],"clauses":[],"itgc":"operations"},
{"code":"DSS03.04","name":"Resolve and close problems.","title":"Problemlerin kalıcı çözümü ve kapatılması","expectation":"Kalıcı çözümler değişiklik yönetimi aracılığıyla test edilip onaylanarak uygulanır; problem, çözümün etkinliği kuruma göre belirlenmiş bir gözlem süresinde doğrulandıktan sonra kapatılır. Maliyet veya risk nedeniyle çözümü uygulanmayan problemler için yetkili kişilerce risk kabulü verilir.","design":"Problem kapanışının değişiklik kaydına ve etkinlik doğrulamasına bağlanıp bağlanmadığı ile risk kabul yetkisinin tanımlı olup olmadığı incelenir.","operating":"Kapatılmış problemlerden seçilen örneklerde ilişkili değişiklik kaydı, onay ve kapanış sonrasında olayların tekrarlanıp tekrarlanmadığı incelenir; risk kabulüyle kapatılanlarda onaycının yetkisi kontrol edilir.","evidence":["Kapatılmış problem kayıtları ve bağlı değişiklik kayıtları","Kapanış sonrası olay tekrar analizi","Risk kabul formları","Problem kapanış kriterleri"],"findings":["Kapatılan bazı problemlere bağlı olayların kapanıştan sonra da tekrarlandığı görülmüştür.","Çözümü ertelenen problemlerin risk kabulü alınmadan kapatıldığı tespit edilmiştir."],"iso":["5.27","8.32"],"clauses":["10.2"],"itgc":"operations"},
{"code":"DSS03.05","name":"Perform proactive problem management.","title":"Proaktif problem yönetimi ve eğilim analizi","expectation":"Olay, izleme ve kapasite verileri kuruma göre belirlenmiş aralıklarla analiz edilerek henüz kesintiye dönüşmemiş zayıflıklar belirlenir; bulgular sahibi ve hedef tarihi olan iyileştirme aksiyonlarına dönüştürülür. Açık problem yaşı ve tekrar oranı gibi göstergeler yönetime raporlanır.","design":"Eğilim analizinin sorumlusu, sıklığı ve aksiyon takip mekanizmasının tanımlı olup olmadığı incelenir.","operating":"Dönemdeki eğilim analizi raporları ve bunlardan doğan aksiyonların tamamlanma durumu incelenir; seçilen aksiyonların gerçekten uygulandığı kanıtla doğrulanır.","evidence":["Eğilim analizi raporları","Proaktif iyileştirme aksiyon listesi","Problem yönetimi performans göstergeleri","Yönetim gözden geçirme kayıtları"],"findings":["Eğilim analizinin yalnızca olay sayılarını raporladığı ve aksiyon üretmediği görülmüştür.","Belirlenen iyileştirme aksiyonlarının sahibi ve hedef tarihi olmadığı tespit edilmiştir."],"iso":["5.27"],"clauses":["9.1","10.1"],"itgc":""}
]},
{"objective":"DSS04","purpose":"Süreklilik yönetimi, ciddi bir kesinti veya felaket durumunda kritik iş süreçlerinin ve bunları destekleyen BT hizmetlerinin kabul edilebilir sürede ve kabul edilebilir veri kaybıyla geri getirilmesini sağlar. Kurtarma hedefleri iş etki analizine dayanmadığında ya da planlar test edilmediğinde, planın işlemediği ancak kriz anında anlaşılır.","auditFocus":"Denetçi, RTO ve RPO değerlerinin iş etki analizinden türetildiğini, teknik kurtarma kabiliyetinin bu hedefleri karşıladığını ve bunun gerçekçi testlerle kanıtlandığını inceler. Yedeklemelerin izlenmesi, özellikle geri yükleme testleri ve test bulgularının planlara yansıtılması öncelikli konulardır.","keyRisks":["İş etki analizine dayanmayan kurtarma hedefleri nedeniyle kritik hizmetlerin kabul edilemez sürede geri gelmesi","Yedeklerin eksik, bozuk veya fidye yazılımından etkilenmiş olması nedeniyle geri yüklenememesi","Test edilmemiş veya güncel olmayan planlar nedeniyle kriz anında koordinasyon eksikliği"],"practices":[
{"code":"DSS04.01","name":"Define the business continuity policy, objectives and scope.","title":"Süreklilik politikası, kapsamı ve kurtarma hedefleri","expectation":"Üst yönetimce onaylanmış bir iş sürekliliği politikası kapsamı, rolleri ve yönetişimi tanımlar. Kritik iş süreçleri ve bağımlı BT hizmetleri iş etki analiziyle belirlenir; her biri için RTO ve RPO iş sahipleri tarafından iş etkisine göre belirlenir ve kuruma göre belirlenmiş aralıklarla ya da önemli değişikliklerde güncellenir.","design":"İş etki analizinin uygulama, altyapı ve tedarikçi bağımlılıklarını kapsayıp kapsamadığı ve RTO/RPO değerlerinin iş sahiplerince onaylanıp onaylanmadığı değerlendirilir.","operating":"Güncel iş etki analizi ve onay kayıtları incelenir; kritik uygulama envanteri analizdeki hizmet listesiyle karşılaştırılarak kapsam dışında kalan kritik sistem olup olmadığı belirlenir.","evidence":["Onaylı iş sürekliliği politikası","İş etki analizi raporu ve RTO/RPO tablosu","İş sahiplerinin onay kayıtları","Kritik uygulama ve bağımlılık envanteri"],"findings":["RTO/RPO değerlerinin iş sahipleri yerine yalnızca BT tarafından belirlendiği ve iş etki analiziyle desteklenmediği görülmüştür.","Son dönemde devreye alınan kritik bir uygulamanın iş etki analizinde yer almadığı tespit edilmiştir."],"iso":["5.29","5.30"],"clauses":["4.3","5.2","6.1"],"itgc":"operations"},
{"code":"DSS04.02","name":"Maintain business resilience.","title":"Dayanıklılık stratejisinin belirlenmesi ve sürdürülmesi","expectation":"Kritik hizmetler için tek hata noktaları belirlenir ve yedekli altyapı, ikincil veri merkezi, bulut bölgeleri, alternatif tedarikçi veya manuel geçici çalışma gibi seçenekler iş etkisiyle orantılı biçimde, maliyet ve fayda dikkate alınarak seçilir. Seçilen strateji yönetimce onaylanır ve kalan riskler açıkça kabul edilir.","design":"Strateji seçiminin RTO/RPO ve risk değerlendirmesine dayanıp dayanmadığı ve tek hata noktalarının tanımlanıp tanımlanmadığı incelenir.","operating":"Kritik hizmetlerden seçilen örneklerde mimari ve yedeklilik düzenlemelerinin onaylı stratejiyle tutarlı olduğu ve kalan riskler için kabul kaydı bulunduğu doğrulanır.","evidence":["Süreklilik stratejisi dokümanı ve yönetim onayı","Kritik hizmet mimari diyagramları ve yedeklilik düzenlemeleri","Tek hata noktası analizi","Risk kabul kayıtları"],"findings":["Kritik bir hizmetin tek veri merkezinde çalıştığı ve bu riskin kabul edildiğine dair kayıt bulunmadığı görülmüştür.","Kritik tedarikçilerin süreklilik kabiliyetinin strateji belirlenirken değerlendirilmediği tespit edilmiştir."],"iso":["5.30","8.14"],"clauses":["6.1"],"itgc":"operations"},
{"code":"DSS04.03","name":"Develop and implement a business continuity response.","title":"İş sürekliliği ve felaket kurtarma planlarının hazırlanması","expectation":"BCP ve DRP; kriz yönetim ekibini, aktivasyon kriterlerini, iletişim zincirini, sistem kurtarma sırasını, alternatif çalışma düzenlerini ve tedarikçi irtibatlarını içerir. Teknik kurtarma prosedürleri adım adım yazılmıştır; planların sahipleri bellidir ve birincil sistemler çalışmasa da erişilebilecek şekilde saklanır.","design":"Planların her kritik hizmet için kurtarma adımlarını, bağımlılık sırasını ve RTO/RPO hedefine nasıl ulaşılacağını içerip içermediği değerlendirilir.","operating":"Seçilen kritik hizmetlerin planları incelenerek iletişim listeleri, sistem adları ve prosedürlerin güncel altyapıyla uyumlu olduğu doğrulanır; planın birincil ortam dışında erişilebilir olduğu kontrol edilir.","evidence":["Onaylı BCP ve DRP dokümanları","Kriz yönetim ekibi ve iletişim listesi","Teknik kurtarma prosedürleri (runbook)","Planların alternatif saklama yerine ait kanıt"],"findings":["DRP içinde artık kullanılmayan sunucu adlarının ve ayrılmış personelin yer aldığı görülmüştür.","Planların yalnızca kesintiden etkilenebilecek dosya sunucusunda saklandığı tespit edilmiştir."],"iso":["5.29","5.30"],"clauses":["8.1"],"itgc":"operations"},
{"code":"DSS04.04","name":"Exercise, test and review the business continuity plan (BCP) and disaster response plan (DRP).","title":"BCP ve DRP testleri ile sonuçların değerlendirilmesi","expectation":"Planlar kuruma göre belirlenmiş bir test programı çerçevesinde masa başı tatbikattan teknik yük devrine kadar farklı düzeylerde test edilir. Test hedefleri önceden tanımlanır, gerçekleşen kurtarma süresi ve veri kaybı RTO/RPO ile karşılaştırılır, iş kullanıcıları uygulama doğrulamasına katılır ve sapmalar için düzeltici aksiyonlar takip edilir.","design":"Test programının tüm kritik hizmetleri makul bir döngüde kapsayıp kapsamadığı ve başarı kriterlerinin RTO/RPO hedeflerine bağlanıp bağlanmadığı değerlendirilir.","operating":"Dönemde yapılan test raporlarında ölçülen sürelerin hedeflerle karşılaştırması, katılımcılar ve aksiyonların kapanışı doğrulanır; programda planlanıp yapılmayan testler belirlenir.","evidence":["Test programı ve kapsamı","Test planları ve başarı kriterleri","Ölçülen kurtarma süresi ve veri kaybını içeren test sonuç raporları","Test bulguları aksiyon takip listesi"],"findings":["DR testinde ölçülen kurtarma süresinin hedefi aştığı ancak düzeltici aksiyon tanımlanmadığı görülmüştür.","Testlerin yalnızca altyapı düzeyinde yapıldığı ve iş kullanıcılarının uygulama doğrulamasına katılmadığı tespit edilmiştir."],"iso":["5.30"],"clauses":["9.1"],"itgc":"operations"},
{"code":"DSS04.05","name":"Review, maintain and improve the continuity plans.","title":"Süreklilik planlarının güncel tutulması ve iyileştirilmesi","expectation":"Planlar test sonuçları, organizasyon değişiklikleri, yeni sistemler ve gerçek kesinti deneyimleri gibi tetikleyicilerle güncellenir; sürüm kontrolü uygulanır ve değişiklikler plan sahibince onaylanır. Yönetim, süreklilik hazırlığını kuruma göre belirlenmiş aralıklarla gözden geçirir.","design":"Güncelleme tetikleyicilerinin değişiklik yönetimiyle bağlantılı olup olmadığı, örneğin yeni bir kritik sistem devreye alındığında plan güncellemesinin zorunlu tutulup tutulmadığı incelenir.","operating":"Plan sürüm geçmişi dönemdeki önemli değişiklikler ve test bulgularıyla karşılaştırılarak güncellemelerin zamanında yapıldığı doğrulanır.","evidence":["Plan sürüm geçmişi ve onayları","Yönetim gözden geçirme tutanakları","Test bulgularının plana yansıtıldığına dair kanıt","Değişiklik kayıtlarındaki süreklilik etki değerlendirmesi"],"findings":["Önemli bir altyapı taşımasından sonra DRP'nin güncellenmediği görülmüştür.","Plan değişikliklerinin sürümlendirilmediği ve onaylanmadığı tespit edilmiştir."],"iso":["5.29","5.30"],"clauses":["9.3","10.1"],"itgc":"operations"},
{"code":"DSS04.06","name":"Conduct continuity plan training.","title":"Süreklilik rollerine yönelik eğitim","expectation":"Kriz ekibi ve kurtarma rollerindeki personel sorumluluklarına uygun eğitim alır; kilit roller için yedek kişiler belirlenmiş ve eğitilmiştir. Eğitim kayıtları tutulur ve yeni atananlar kuruma göre belirlenmiş süre içinde eğitilir.","design":"Eğitim ihtiyacının rollere göre tanımlanıp tanımlanmadığı ve yedek personel planlamasının yapılıp yapılmadığı incelenir.","operating":"Plandaki rol listesi eğitim kayıtlarıyla karşılaştırılarak eğitimsiz rol sahibi olup olmadığı belirlenir; seçilen kişilerle görüşülerek rollerine hakimiyetleri değerlendirilir.","evidence":["Rol bazlı eğitim planı","Eğitim katılım kayıtları","Kriz ekibi rol ve yedek listesi","Tatbikat katılım kayıtları"],"findings":["Kriz ekibindeki bazı yedek rollerin hiç eğitim almadığı görülmüştür.","Eğitim kayıtlarının tutulmadığı ve katılımın doğrulanamadığı tespit edilmiştir."],"iso":["6.3"],"clauses":["7.2","7.3"],"itgc":""},
{"code":"DSS04.07","name":"Manage backup arrangements.","title":"Yedekleme, yedeklerin korunması ve geri yükleme testleri","expectation":"Yedekleme kapsamı, sıklığı ve saklama süreleri RPO, saklama yükümlülükleri ve veri sınıflandırmasına göre kuruma göre belirlenir. Yedek işlerinin sonucu düzenli izlenir ve başarısızlıklar olay olarak ele alınır; yedekler şifrelenir, en az bir kopya mantıksal veya fiziksel olarak ayrık (değiştirilemez ya da çevrimdışı) tutulur ve geri yükleme testleri planlı olarak yapılıp sonuçları belgelenir.","design":"Yedekleme politikasının tüm kritik sistemleri kapsayıp kapsamadığı, yedek ortamına erişimin kısıtlı olup olmadığı ve geri yükleme testinin zorunlu kılınıp kılınmadığı değerlendirilir.","operating":"Kritik sistem envanteri yedekleme aracındaki iş listesiyle karşılaştırılır; dönem boyunca yedek iş geçmişinden başarısızlıklar ve takipleri incelenir, geri yükleme test kayıtlarından seçilen örneklerde verinin bütünlüğü ve süresi doğrulanır.","evidence":["Yedekleme politikası ve sistem bazlı yedekleme matrisi","Yedekleme aracı iş geçmişi ve hata kayıtları","Geri yükleme test kayıtları ve doğrulama sonuçları","Yedek ortamına erişim yetkili listesi ile değiştirilemez veya çevrimdışı kopya yapılandırması"],"findings":["Bazı kritik veri tabanlarının yedekleme işine dahil edilmediği görülmüştür.","Geri yükleme testlerinin yalnızca tek dosya düzeyinde yapıldığı ve tam sistem kurtarmanın hiç denenmediği tespit edilmiştir."],"iso":["8.13","5.30"],"clauses":[],"itgc":"operations"},
{"code":"DSS04.08","name":"Conduct post-resumption review.","title":"Kesinti sonrası değerlendirme","expectation":"Planın devreye alındığı her gerçek kesinti veya ciddi olaydan sonra, hizmet olağan işleyişe döndüğünde yapılandırılmış bir değerlendirme yapılır. Planın etkinliği, hedeflere uyum, iletişim ve karar süreçleri değerlendirilir; çıkarılan dersler plana ve sahipli aksiyonlara aktarılır.","design":"Kesinti sonrası değerlendirmenin zorunlu tutulup tutulmadığı ve sonuçlarının plan güncellemesine bağlanıp bağlanmadığı incelenir.","operating":"Dönemdeki plan aktivasyonları ve büyük kesintiler listelenerek her biri için değerlendirme raporu bulunup bulunmadığı ve aksiyonların kapatıldığı doğrulanır.","evidence":["Plan aktivasyon kayıtları","Kesinti sonrası değerlendirme raporları","Ders çıkarım aksiyon listesi","Güncellenmiş plan sürümleri"],"findings":["Gerçek bir veri merkezi kesintisinin ardından değerlendirme yapılmadığı görülmüştür.","Değerlendirme aksiyonlarının sahipsiz kaldığı ve plana yansıtılmadığı tespit edilmiştir."],"iso":["5.27","5.29"],"clauses":["10.2"],"itgc":"operations"}
]},
{"objective":"DSS05","purpose":"Güvenlik hizmetleri; kötü amaçlı yazılım, ağ, uç nokta, kimlik ve erişim, fiziksel erişim ve güvenlik izleme kontrolleriyle bilgi varlıklarını günlük işleyişte korur. Bu alandaki zayıflıklar yetkisiz erişim, veri sızıntısı ve fidye yazılımı gibi olaylara doğrudan kapı açar ve finansal raporlamaya dayanak sistemlerin güvenilirliğini zedeler.","auditFocus":"Kıdemli denetçi; işe giriş, görev değişikliği ve ayrılışta erişimin zamanında verilip kaldırılmasını, ayrıcalıklı erişimin kısıtlanıp izlenmesini ve periyodik erişim gözden geçirmelerinin etkinliğini öncelikli olarak test eder. Bunun yanında güvenlik günlüklerinin toplanıp izlenmesi, zafiyetlerin risk bazlı giderilmesi ve uç nokta ile ağ korumalarının kapsamı değerlendirilir.","keyRisks":["Ayrılan veya görev değiştiren personelin erişimlerinin zamanında kaldırılmaması ve ayrıcalıklı hesapların kötüye kullanılması","Yamalanmamış zafiyetler ve koruma kapsamı dışındaki uç noktalar üzerinden kötü amaçlı yazılım yayılması","Güvenlik olaylarının günlük eksikliği veya izleme yapılmaması nedeniyle geç tespit edilmesi"],"practices":[
{"code":"DSS05.01","name":"Protect against malicious software.","title":"Kötü amaçlı yazılımlara karşı koruma","expectation":"Tüm uç nokta ve sunucularda merkezi yönetilen kötü amaçlı yazılım koruması (antivirüs veya EDR) kuruludur; imza ve motor güncellemeleri otomatik dağıtılır ve kullanıcılar korumayı devre dışı bırakamaz. E-posta ve web ağ geçitlerinde filtreleme yapılır, tespitler merkezi konsolda izlenir ve olay sürecine aktarılır; kullanıcı farkındalığı bu teknik önlemleri destekler.","design":"Koruma politikasının tüm platformları kapsayıp kapsamadığı, kurcalamaya karşı korumanın etkin olup olmadığı ve merkezi uyarı akışının tasarlanıp tasarlanmadığı değerlendirilir.","operating":"Varlık envanteri ile koruma konsolundaki ajan listesi karşılaştırılarak kapsam ve güncellik oranı belirlenir; dönem içi tespitlerden seçilen örneklerin olay sürecinde ele alındığı doğrulanır.","evidence":["Koruma konsolundan ajan durumu ve sürüm raporu","Varlık envanteri ile kapsam karşılaştırması","Koruma politikası ayarları ve kurcalama koruması yapılandırması","Tespit uyarıları ve ilişkili olay kayıtları"],"findings":["Bazı sunucularda koruma ajanının kurulu olmadığı veya uzun süredir merkezi konsola raporlamadığı görülmüştür.","Yerel yönetici yetkisine sahip kullanıcıların korumayı devre dışı bırakabildiği tespit edilmiştir."],"iso":["8.7","6.3"],"clauses":[],"itgc":""},
{"code":"DSS05.02","name":"Manage network and connectivity security.","title":"Ağ ve bağlantı güvenliği","expectation":"Ağ, varlıkların kritikliğine göre bölümlere ayrılmıştır ve bölgeler arası trafik güvenlik duvarı kurallarıyla en az ayrıcalık ilkesine göre sınırlanır. Kural değişiklikleri onaylı değişiklik sürecinden geçer ve kural seti kuruma göre belirlenmiş aralıklarla gözden geçirilir; uzaktan erişim çok faktörlü kimlik doğrulamayla korunur ve hassas veri aktarımları şifrelenir.","design":"Segmentasyon tasarımının üretim veri tabanları gibi kritik sistemleri ayırıp ayırmadığı, kural değişikliği ve kural gözden geçirme süreçlerinin tanımlı olup olmadığı değerlendirilir.","operating":"Güvenlik duvarı yapılandırma dökümü salt okunur olarak alınıp geniş kapsamlı izin kuralları analiz edilir; dönem içi kural değişikliklerinden seçilen örnekler değişiklik onaylarıyla eşleştirilir ve son kural gözden geçirmesinin kanıtı incelenir.","evidence":["Ağ topolojisi ve segmentasyon şeması","Güvenlik duvarı kural seti dökümü ve son gözden geçirme kaydı","Kural değişikliği talep ve onay kayıtları","Uzaktan erişim yapılandırması ve çok faktörlü kimlik doğrulama ayarları"],"findings":["Güvenlik duvarında gerekçesi belgelenmemiş geniş kapsamlı izin kuralları bulunduğu görülmüştür.","Bazı tedarikçi uzaktan erişim bağlantılarında çok faktörlü kimlik doğrulamanın uygulanmadığı tespit edilmiştir."],"iso":["8.20","8.21","8.22","8.24"],"clauses":[],"itgc":"access"},
{"code":"DSS05.03","name":"Manage endpoint security.","title":"Uç nokta güvenliği ve güvenli yapılandırma","expectation":"Dizüstü, masaüstü, mobil cihaz ve sunucular onaylı güvenli yapılandırma standartlarına göre kurulur; disk şifreleme, ekran kilidi, yerel yönetici yetkisinin kısıtlanması ve çıkarılabilir ortam kontrolleri uygulanır. Cihazlar merkezi yönetim aracına kayıtlıdır, yamalar risk bazlı ve kuruma göre belirlenmiş sürelerde dağıtılır ve standarttan sapmalar izlenir.","design":"Yapılandırma standartlarının onaylanıp onaylanmadığı ve uyumun mobil cihaz yönetimi veya grup politikası gibi araçlarla teknik olarak zorlanıp izlenebildiği değerlendirilir.","operating":"Merkezi yönetim aracından cihaz uyum raporu alınıp envanterle karşılaştırılır; risk bazlı seçilen cihazlarda şifreleme, yerel yönetici üyeliği ve yama durumu salt okunur olarak incelenir.","evidence":["Onaylı güvenli yapılandırma standartları","Cihaz yönetim aracı uyum raporu","Disk şifreleme durum raporu","Yerel yönetici grubu üyelik listesi"],"findings":["Dizüstü bilgisayarların bir kısmında disk şifrelemenin etkin olmadığı görülmüştür.","Çok sayıda kullanıcının gerekçe olmaksızın yerel yönetici yetkisine sahip olduğu tespit edilmiştir."],"iso":["8.1","8.9","7.9"],"clauses":[],"itgc":""},
{"code":"DSS05.04","name":"Manage user identity and logical access.","title":"Kullanıcı kimlikleri ve mantıksal erişim yönetimi","expectation":"Her kullanıcıya bireysel ve sahibi belli bir kimlik verilir; erişimler iş rolüne ve en az ayrıcalık ilkesine göre, veri veya sistem sahibinin onayıyla tanımlanır. Ayrılış ve görev değişikliklerinde insan kaynakları kaynaklı tetikleyiciyle erişimler kuruma göre belirlenmiş süre içinde kaldırılır veya güncellenir; ayrıcalıklı hesaplar ayrı tutulur, çok faktörlü kimlik doğrulamayla korunur ve faaliyetleri izlenir, erişimler de kuruma göre belirlenmiş aralıklarla sistem sahiplerince gözden geçirilir.","design":"Erişim verme, değiştirme, kaldırma ve gözden geçirme süreçlerinin İK kaynağına bağlı, onaylı ve görevler ayrılığını gözetecek şekilde tasarlanıp tasarlanmadığı; ortak, hizmet ve acil durum hesaplarının nasıl yönetildiği değerlendirilir.","operating":"İK’dan alınan ayrılış listesi ile tamlığı doğrulanmış sistem kullanıcı listeleri karşılaştırılarak ayrılan kişilerin aktif hesapları belirlenir; risk bazlı seçilen yeni erişimlerde onay izi, ayrıcalıklı hesaplarda gerekçe ve periyodik gözden geçirmede kaldırılması istenen yetkilerin gerçekten kaldırıldığı yeniden uygulama ile doğrulanır.","evidence":["İK işe giriş, ayrılış ve görev değişikliği listeleri","Kritik uygulama, veri tabanı ve işletim sistemi kullanıcı ve yetki listeleri ile sistemden alındığına dair kanıt","Erişim talep ve onay kayıtları ile periyodik erişim gözden geçirme kanıtları","Ayrıcalıklı hesap envanteri, ayrıcalıklı erişim yönetimi kayıtları ve parola/çok faktörlü doğrulama ayarları"],"findings":["İşten ayrılan bazı personelin kritik uygulamadaki hesaplarının ayrılış tarihinden sonra da aktif kaldığı ve bir kısmında oturum açıldığı görülmüştür.","Periyodik erişim gözden geçirmesinin tam olmayan bir kullanıcı listesi üzerinden yapıldığı ve kaldırılması istenen yetkilerin sistemde değiştirilmediği tespit edilmiştir."],"iso":["5.15","5.16","5.18","8.2"],"clauses":[],"itgc":"access"},
{"code":"DSS05.05","name":"Manage physical access to I&T assets.","title":"BT varlıklarına fiziksel erişimin yönetimi","expectation":"Veri merkezi, sistem odaları ve ağ kabinlerine fiziksel erişim iş ihtiyacına göre ve sorumlu yöneticinin onayıyla verilir, kartlı geçiş veya biyometrik kontrol gibi mekanizmalarla sınırlandırılır. Ziyaretçiler kayda alınır ve refakat edilir; yetkiler ayrılışlarda kaldırılır, kuruma göre belirlenmiş aralıklarla gözden geçirilir ve geçiş ile kamera kayıtları saklanır.","design":"Fiziksel erişim verme ve kaldırma sürecinin İK tetikleyicisine bağlı olup olmadığı ve hassas alanların ayrı yetki bölgesi olarak tanımlanıp tanımlanmadığı değerlendirilir.","operating":"Geçiş kontrol sisteminden veri merkezi yetkili listesi alınarak İK ayrılış listesi ve iş ihtiyacıyla karşılaştırılır; ziyaretçi kayıtlarından seçilen örneklerde onay ve refakat doğrulanır, yerinde gözlem yapılır.","evidence":["Geçiş kontrol sistemi veri merkezi yetkili listesi","Fiziksel erişim talep ve onay kayıtları","Ziyaretçi kayıtları","Fiziksel erişim gözden geçirme kanıtı"],"findings":["Veri merkezine erişim yetkisi olanlar arasında artık bu ihtiyacı olmayan veya kurumdan ayrılmış kişiler bulunduğu görülmüştür.","Tedarikçi teknisyenlerinin ziyaret kayıtlarında refakatçi bilgisinin yer almadığı tespit edilmiştir."],"iso":["7.1","7.2","7.3","7.4"],"clauses":[],"itgc":"access"},
{"code":"DSS05.06","name":"Manage sensitive documents and output devices.","title":"Hassas dokümanlar, çıktı cihazları ve ortamların korunması","expectation":"Hassas basılı belgeler, kıymetli evrak (çek, kart, sertifika gibi) ve çıktı cihazları için sınıflandırmaya uygun saklama, envanter ve teslim kuralları vardır. Yazıcılarda kimlik doğrulamalı güvenli baskı kullanılır, ortamlar ve belgeler kayıtlı ve onaylı biçimde imha edilir, temiz masa ve temiz ekran kuralları uygulanır.","design":"Hassas belge ve ortamlar için sınıflandırma politikasına bağlı saklama, taşıma ve imha kurallarının tanımlanıp tanımlanmadığı değerlendirilir.","operating":"Kıymetli evrak envanteri fiziksel sayımla mutabakatlanır; imha kayıtlarından seçilen örnekler incelenir ve yerinde gözlemle temiz masa uygulaması, yazıcı tepsileri ve kilitli dolaplar kontrol edilir.","evidence":["Kıymetli evrak ve hassas ortam envanteri ile sayım tutanakları","Güvenli imha kayıtları ve sertifikaları","Yazıcı güvenli baskı yapılandırması","Temiz masa ve ekran gözlem kontrol listesi"],"findings":["Yazıcı tepsilerinde sahipsiz bırakılmış kişisel veri içeren çıktılar gözlemlenmiştir.","Hurdaya ayrılan disklerin imha edildiğine dair kanıt bulunmadığı tespit edilmiştir."],"iso":["5.13","7.7","7.10","7.14"],"clauses":[],"itgc":""},
{"code":"DSS05.07","name":"Manage vulnerabilities and monitor the infrastructure for security-related events.","title":"Zafiyet yönetimi ve güvenlik olay izleme","expectation":"Altyapı ve uygulamalar kuruma göre belirlenmiş sıklıkta ve yetkilendirilmiş şekilde zafiyet taramasından geçirilir; bulgular kritiklik ve maruziyete göre önceliklendirilip tanımlı sürelerde giderilir ya da risk kabulüne bağlanır. Kritik sistemlerin güvenlik günlükleri merkezi bir sisteme (SIEM gibi) toplanır, değiştirilmeye karşı korunur, kuruma göre belirlenmiş süre saklanır ve korelasyon kurallarıyla izlenerek şüpheli olaylar müdahale sürecine aktarılır.","design":"Tarama kapsamının, giderim sürelerinin ve günlük kaynaklarının kritik varlıkları kapsayıp kapsamadığı; izleme kurallarının ayrıcalıklı hesap kullanımı ve başarısız oturum açma gibi senaryoları içerip içermediği değerlendirilir.","operating":"Varlık envanteri tarama kapsamı ve SIEM günlük kaynaklarıyla karşılaştırılır; kritik zafiyetlerden seçilen örneklerde giderim süresi ve risk kabulleri, alarmlardan seçilen örneklerde inceleme ve kapanış izi doğrulanır. Denetçi kendisi tarama yapmaz, mevcut sonuçları salt okunur inceler.","evidence":["Zafiyet tarama raporları ve giderim takip listesi","Risk kabulü verilmiş zafiyet kayıtları","SIEM günlük kaynak listesi ve saklama ayarları","SIEM alarmları ve ilişkili inceleme ile olay kayıtları"],"findings":["Kritik zafiyetlerin bir kısmının kurumun belirlediği giderim süresini aştığı ve risk kabulü bulunmadığı görülmüştür.","Bazı kritik veri tabanı sunucularının günlüklerinin merkezi izleme sistemine gönderilmediği tespit edilmiştir."],"iso":["8.8","8.15","8.16","5.25"],"clauses":["9.1"],"itgc":"operations"}
]},
{"objective":"DSS06","purpose":"İş süreçlerine gömülü otomatik ve manuel kontroller, işlemlerin eksiksiz, doğru, yetkili ve zamanında işlenmesini sağlar; finansal raporlama ve operasyonel kararlar bu verilerin güvenilirliğine dayanır. Kontroller iş hedefleri ve risklerle uyumlu tasarlanmadığında hatalı ödemeler, mükerrer kayıtlar veya yetkisiz işlemler fark edilmeden birikebilir.","auditFocus":"Denetçi, girdi, işleme ve çıktı kontrollerini (doğrulama kuralları, eşleştirmeler, mutabakatlar, onay limitleri) ve iş süreçlerindeki görevler ayrılığını uçtan uca inceler. Hata ve istisnaların zamanında çözülmesi, işlemlerin izlenebilirliği ve otomatik kontrol ayarlarının yetkisiz değişikliğe karşı korunması özellikle değerlendirilir.","keyRisks":["Eksik veya hatalı veri girişinin doğrulama kontrolleriyle yakalanmaması ve finansal tablolara yansıması","Görevler ayrılığı çatışmaları nedeniyle tek kişinin bir işlemi başlatıp onaylayabilmesi","İstisna ve mutabakat farklarının sahipsiz kalarak birikmesi"],"practices":[
{"code":"DSS06.01","name":"Align control activities embedded in business processes with enterprise objectives.","title":"İş süreci kontrollerinin hedef ve risklerle hizalanması","expectation":"Kritik iş süreçleri için süreç sahiplerini, temel riskleri ve bu risklere karşılık gelen otomatik ve manuel kontrolleri gösteren bir risk-kontrol matrisi bulunur. Kontrol sahibi, sıklığı ve üretilecek kanıt bellidir; matris süreç veya sistem değişikliklerinde güncellenir ve kontrol etkinliği süreç sahiplerince izlenir.","design":"Risk-kontrol matrisinin kritik riskleri ele alıp almadığı, önleyici ve tespit edici kontrol dengesinin ve kontrol sahipliğinin uygun olup olmadığı değerlendirilir.","operating":"Seçilen süreçlerde uçtan uca süreç izlemesi (walkthrough) yapılarak matristeki kontrollerin gerçekte uygulandığı doğrulanır; dönemdeki süreç değişikliklerinden sonra matrisin güncellendiği kontrol edilir.","evidence":["Süreç risk-kontrol matrisleri","Süreç akış şemaları ve süreç izleme notları","Kontrol sahipliği ve öz değerlendirme sonuçları","Matris güncelleme kayıtları"],"findings":["Matriste yer alan bazı kontrollerin sistem değişikliği sonrasında artık uygulanmadığı görülmüştür.","Kritik bir süreç riskine karşılık gelen bir kontrol tanımlanmadığı tespit edilmiştir."],"iso":[],"clauses":["6.1","8.1"],"itgc":""},
{"code":"DSS06.02","name":"Control the processing of information.","title":"Bilgi işleme kontrolleri: girdi, işleme ve çıktı","expectation":"Uygulamalarda zorunlu alan, format, değer aralığı ve mükerrerlik gibi giriş doğrulama kuralları; arayüz ve toplu aktarımlarda kayıt sayısı ve kontrol toplamı karşılaştırmaları ile kritik hesaplamalar tanımlıdır. Otomatik kontrol ayarları değişiklik yönetimi altındadır; alt sistemlerle ana defter arasında kuruma göre belirlenmiş sıklıkta mutabakat yapılır ve bağımsız biri tarafından gözden geçirilir.","design":"Kritik veri akışlarında tamlık ve doğruluk kontrollerinin tasarlanıp tasarlanmadığı ve otomatik kontrol yapılandırmalarının yetkisiz değişikliğe karşı korunup korunmadığı değerlendirilir.","operating":"Otomatik kontroller yapılandırma incelemesi ve gözlem ya da test ortamında yeniden uygulama ile doğrulanır, değişiklik kontrolleri etkinse dönem boyunca değişmediğine dayanılır; manuel mutabakatlarda risk bazlı seçilen örneklerde farkların araştırılıp onaylandığı incelenir.","evidence":["Uygulama doğrulama kuralları ve yapılandırma ekran görüntüleri","Arayüz kontrol toplamı raporları ve reddedilen kayıt listeleri","Alt sistem ile ana defter mutabakatları ve onayları","Otomatik kontrol yapılandırma değişiklik kayıtları"],"findings":["Arayüz aktarımlarında kayıt sayısı karşılaştırması yapılmadığı ve reddedilen kayıtların izlenmediği görülmüştür.","Mutabakat farklarının açıklama ve onay olmadan sonraki döneme taşındığı tespit edilmiştir."],"iso":[],"clauses":["8.1"],"itgc":""},
{"code":"DSS06.03","name":"Manage roles, responsibilities, access privileges and levels of authority.","title":"İş rolleri, onay yetkileri ve görevler ayrılığı","expectation":"İş rolleri ve onay limitlerini gösteren yetki matrisi yönetimce onaylanmıştır ve uygulamadaki yetkiler bu rollere eşlenmiştir. Tedarikçi kaydı oluşturma ile ödeme onaylama gibi çatışan görevler için kurallar tanımlıdır; çatışmalar önlenir, kaçınılmaz olanlara telafi edici kontrol uygulanır ve yetkiler kuruma göre belirlenmiş aralıklarla iş sahiplerince gözden geçirilir.","design":"Çatışma kural setinin kritik işlem kombinasyonlarını kapsayıp kapsamadığı ve onay limitlerinin sistemde zorlanıp zorlanmadığı değerlendirilir.","operating":"Uygulama yetki verisi alınarak tüm kullanıcı popülasyonu çatışma kural setine göre veri analiziyle incelenir; tespit edilen çatışmalarda fiilen işlem yapılıp yapılmadığı ve telafi edici kontrollerin çalıştığı incelenir, onay limitleri seçilen işlemler üzerinde yeniden uygulanır.","evidence":["Onaylı yetki matrisi ve onay limitleri","Uygulama rol-yetki dökümü ve kullanıcı-rol atamaları","Görevler ayrılığı çatışma analizi sonuçları","Telafi edici kontrol kanıtları ve yetki gözden geçirme kayıtları"],"findings":["Bazı kullanıcıların hem tedarikçi ana verisini değiştirme hem de ödeme onaylama yetkisine sahip olduğu görülmüştür.","Sistemde tanımlı onay limitlerinin onaylı yetki matrisiyle uyuşmadığı tespit edilmiştir."],"iso":["5.3","5.15","5.18","8.2"],"clauses":["5.3"],"itgc":"access"},
{"code":"DSS06.04","name":"Manage errors and exceptions.","title":"İşlem hataları ve istisnaların yönetimi","expectation":"İşlem hataları, reddedilen kayıtlar ve limit aşımı ya da eşleşmeyen fatura gibi kontrol istisnaları kayda alınır, sahiplerine atanır ve kuruma göre belirlenmiş sürelerde düzeltilir. Düzeltmeler asıl kontrolleri atlatmayacak şekilde onaylı yapılır ve istisna eğilimleri kök neden açısından analiz edilir.","design":"İstisna raporlarının üretilip üretilmediği, sahiplerinin belli olup olmadığı ve düzeltmelerin onay gerektirip gerektirmediği değerlendirilir.","operating":"Dönemin istisna ve hata raporları alınarak yaşlandırma analizi yapılır; seçilen istisnalarda çözümün, onayın ve düzeltme yönteminin uygunluğu incelenir.","evidence":["Yaşlandırma bilgisi içeren istisna ve hata raporları","Hata düzeltme kayıtları ve onayları","Askı hesap analizleri","İstisna eğilim analizleri"],"findings":["Arayüzden reddedilen kayıtların uzun süre düzeltilmeden askıda bekletildiği görülmüştür.","Hata düzeltmelerinin doğrudan veri tabanında, onay ve iz bırakılmadan yapıldığı tespit edilmiştir."],"iso":[],"clauses":["10.2"],"itgc":""},
{"code":"DSS06.05","name":"Ensure traceability and accountability for information events.","title":"İşlemlerin izlenebilirliği ve hesap verebilirlik","expectation":"Kritik işlemlerde kimin, neyi, ne zaman yaptığı ve onayladığı uygulama denetim izleriyle kaydedilir; ana veri ve hassas alan değişiklikleri ayrıca izlenir. Denetim izleri değiştirilmeye ve silinmeye karşı korunur, kuruma göre belirlenmiş süre saklanır ve işlemler kaynak belgeleriyle ilişkilendirilebilir.","design":"Kritik tablolar ve işlemler için denetim izi kapsamının belirlenip belirlenmediği ve izlerin yetkisiz değişikliğe karşı korunup korunmadığı değerlendirilir.","operating":"Seçilen işlemler kaynak belgeden sistem kaydına ve sistem kaydından kaynak belgeye izlenir; denetim izi ayarları salt okunur incelenir ve ana veri değişiklik raporundan seçilen örneklerin onayı doğrulanır.","evidence":["Uygulama denetim izi yapılandırması","Ana veri değişiklik günlükleri ve onayları","Kaynak belge ile işlem eşleştirme örnekleri","Günlük saklama ve koruma ayarları"],"findings":["Kritik ana veri tablolarında değişiklik günlüğünün kapalı olduğu görülmüştür.","Uygulama yöneticilerinin denetim izi kayıtlarını silebildiği tespit edilmiştir."],"iso":["8.15","5.33"],"clauses":["7.5"],"itgc":""},
{"code":"DSS06.06","name":"Secure information assets.","title":"İş süreçlerindeki bilgi varlıklarının güvenliği","expectation":"İş süreçlerinde kullanılan, aktarılan ve saklanan elektronik ve basılı bilgiler sınıflandırmaya uygun biçimde korunur; kişisel ve gizli veriler için maskeleme, şifreleme ve veri sızıntısı önleme gibi önlemler uygulanır. Süreç sahibi, son kullanıcı hesap tabloları ve sistem dışa aktarımları gibi yapılandırılmamış veri kümelerini de kontrol kapsamında tutar.","design":"Bilgi sınıflandırmasının süreç düzeyindeki koruma kurallarına yansıtılıp yansıtılmadığı ve kritik son kullanıcı araçlarının belirlenip belirlenmediği değerlendirilir.","operating":"Seçilen süreçlerde dışa aktarım, paylaşım ve saklama noktaları incelenir; kritik son kullanıcı araçlarında erişim ve sürüm kontrolleri ile hassas veri aktarımlarında şifreleme kanıtı doğrulanır, incelemede kişisel veriler maskelenmiş örneklerle çalışılır.","evidence":["Bilgi sınıflandırma politikası ve süreç bazlı uygulama kuralları","Kritik son kullanıcı araçları envanteri ve kontrolleri","Veri sızıntısı önleme politika ve olay raporları","Hassas veri aktarım yöntemleri ve şifreleme ayarları"],"findings":["Finansal raporlamada kullanılan hesap tablolarının erişim kısıtı ve sürüm kontrolü olmadan paylaşımlı klasörde tutulduğu görülmüştür.","Kişisel veri içeren dışa aktarımların şifrelenmeden e-postayla gönderildiği tespit edilmiştir."],"iso":["5.12","5.14","8.11","8.12"],"clauses":[],"itgc":""}
]}
]
);
